        getPerformanceSummary(history) {
            if (!history || history.length === 0) return { totalPeriods: 0 };

            var last = history[history.length - 1];
            var results = last.results || {};
            var ds = last.domainState || (this._getState() || {}).domainState || {};
            var composite = results.composite || 0;
            var msci = results.msciRating || 'CCC';
            var parts = ds.boardParts || this._boardParts(ds);
            var score = parts.total;
            var perfKey = this._perfKey(score);

            var envTotal = 0, socTotal = 0, govTotal = 0, spend = 0, finYears = [], earlyGov = 0, lateGov = [];
            var turning = null;
            history.forEach(function(h, i) {
                var r = h.results || {};
                envTotal += r.envInvest || 0;
                socTotal += r.socialInvest || 0;
                govTotal += r.govInvest || 0;
                spend += (r.envInvest || 0) + (r.socialInvest || 0) + (r.govInvest || 0);
                if (r.strategy === 'financial') finYears.push(i + 1);
                if (i < 2) earlyGov += r.govInvest || 0; else lateGov.push(r.govInvest || 0);
            });
            var n = history.length;
            var pub = ds.govHistory || [];
            var g = this._builtHistory(ds);
            var e = ds.envScore || 0, so = ds.socialScore || 0, gv = ds.govScore || 0;
            var lateAvg = lateGov.length ? lateGov.reduce(function(a, b) { return a + b; }, 0) / lateGov.length : 0;
            // governance points the events took off the published score by the EU deadline (Year 3)
            var hitAt = Math.min(3, n) - 1;
            var lost = hitAt >= 0 ? Math.round((g[hitAt] || 0) - (pub[hitAt] || 0)) : 0;

            var ins = [];
            var vars = { e: Math.round(e), s: Math.round(so), g: Math.round(gv), c: composite, rating: msci,
                         g2: g.length > 1 ? Math.round(g[1]) : '-', g3: g.length > 2 ? Math.round(g[2]) : '-',
                         lost: lost, year: hitAt + 1, pub: hitAt >= 0 ? Math.round(pub[hitAt]) : '-',
                         years: finYears.join(', '), avg: this._fmt1(spend / Math.max(1, n)) };
            // the rating, as the methodology of the case computes it
            if (composite >= 60) ins.push({ k: 'insight_rating_high', v: vars });
            else if (composite >= 50) ins.push({ k: 'insight_rating_bbb', v: vars });
            else ins.push({ k: 'insight_rating_low', v: vars });
            // M2: the rating carried on one pillar
            if (gv < 40 && Math.max(e, so) - gv >= 30) ins.push({ k: 'insight_single_pillar', v: vars });
            // M1: governance started late (the play), else the activist / EU tests (the outcome)
            var govLate = n >= 3 && earlyGov < 8 && lateAvg >= 6;
            if (govLate) ins.push({ k: 'insight_gov_late', v: vars });
            if (n >= 2 && !govLate) ins.push({ k: g[1] >= 40 ? 'insight_activist_cleared' : 'insight_activist_missed', v: vars });
            if (n >= 3 && !govLate) ins.push({ k: g[2] >= 50 ? 'insight_greenwash_cleared' : 'insight_greenwash_missed', v: vars });
            // the draw, named apart from the play: an event took governance under a line the programme had cleared
            var hitMatters = (n >= 2 && g[1] >= 40 && pub[1] < 40) || (n >= 3 && g[2] >= 50 && pub[2] < 50);
            if (lost >= 1 && hitMatters) ins.push({ k: 'insight_gov_hit', v: vars });
            // M3: the Financial Priority stance
            if (finYears.length) ins.push({ k: 'insight_financial_stance', v: vars });
            // M4: the money left on the table
            if (n >= 3 && spend / n <= 14) ins.push({ k: 'insight_unspent', v: vars });
            if (results.ebitdaMargin && results.ebitdaMargin < 11) ins.push({ k: 'insight_financial_suffered', v: vars });

            // turning point: the first year the plan broke a test, else the year it secured them
            if (finYears.length) turning = { k: 'turning_financial', v: { year: finYears[0] } };
            if (n >= 2 && g[1] < 40 && (!turning || turning.v.year > 2)) turning = { k: 'turning_activist', v: { year: 2, g: Math.round(g[1]) } };
            if (!turning && n >= 3 && g[2] < 50) turning = { k: 'turning_greenwash', v: { year: 3, g: Math.round(g[2]) } };
            if (!turning && n >= 2) turning = { k: 'turning_secured', v: { year: 2, g: Math.round(g[1]) } };

            return {
                totalPeriods: history.length,
                composite: composite,
                msciRating: msci,
                boardScore: score,
                overallScore: score,
                totalScore: score,
                score: score,
                boardParts: parts,
                performanceKey: perfKey,
                performance: perfKey,
                performanceLabel: this._t(perfKey),
                insightKeys: ins.map(function(x) { return x.k; }),
                insightItems: ins,
                turningPoint: turning,
                totalInvestment: envTotal + socTotal + govTotal,
                ebitdaMargin: results.ebitdaMargin || 0,
                message: this._t(ins[0].k, ins[0].v)
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var self = this;
            var items = summary.insightItems || (summary.insightKeys || []).map(function(k) { return { k: k, v: {} }; });
            var insights = items.map(function(x) { return '<li>' + self._t(x.k, x.v) + '</li>'; }).join('');
            var p = summary.boardParts || {};
            var row = function(key, val, max) {
                var v = +val || 0;
                var shown = v === Math.round(v) ? String(v) : self._fmt1(v);
                return '<tr><td>' + self._t(key) + '</td><td class="text-right">' + shown + ' / ' + max + '</td></tr>';
            };
            var label = summary.performanceLabel || this._t(summary.performanceKey || 'perf_needs');
            var tp = summary.turningPoint;

            var html = ''
                + '<div class="esg-completion p-3">'
                + '<h4 class="text-center">' + this._t('completion_title') + '</h4>'
                + '<p class="text-center"><strong>' + this._t('board_score_label') + ':</strong> ' + (summary.boardScore || 0) + '/100'
                + ' &nbsp; <strong>' + this._t('completion_performance') + ':</strong> ' + label + '</p>'
                + '<p class="text-center"><strong>' + this._t('composite_label') + ':</strong> ' + (summary.composite || 0) + '/100'
                + ' &nbsp; <strong>' + this._t('msci_label') + ':</strong> ' + (summary.msciRating || 'CCC')
                + ' &nbsp; <strong>' + this._t('summary_total_invest') + '</strong> $' + (summary.totalInvestment || 0) + 'M</p>'
                + '<table class="table table-sm esg-sim-board-table"><caption>' + this._t('board_parts_caption') + '</caption><tbody>'
                + row('part_rating', p.rating, 35) + row('part_mandate', p.mandate, 15) + row('part_activist', p.activist, 15)
                + row('part_greenwash', p.greenwash, 15) + row('part_margin', p.margin, 10) + row('part_weakest', p.weakest, 10)
                + '</tbody></table>'
                + (tp ? '<p><strong>' + this._t('turning_label') + '</strong> ' + this._t(tp.k, tp.v) + '</p>' : '')
                + (insights ? '<p><strong>' + this._t('completion_insights') + '</strong></p><ul>' + insights + '</ul>' : '')
                + '<p><strong>' + this._t('discussion_label') + '</strong></p><ol><li>' + this._t('discussion_q1') + '</li><li>' + this._t('discussion_q2') + '</li></ol>'
                + '<p class="text-muted text-center">' + this._t('completion_thanks') + '</p>'
                + '</div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            // A missed opportunity is not a crisis — give it its own guidance.
            if (results.eventIsOpportunity && results.eventMitigated === false) {
                return this._t('hint_opportunity_missed');
            }
            if (results.eventMitigated === false) {
                var ev = EVENTS[results.eventIndex] || {};
                return this._t('hint_crisis', { pillar: this._t('pillar_' + (ev.pillar || 'governance')), threshold: ev.threshold || 40 });
            }
            if (results.composite > 65) {
                return this._t('hint_strong');
            }
            if (results.ebitdaMargin < 10) {
                return this._t('hint_financial');
            }
            return null;
        }

